        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the `NO_TIMESTAMP` flag not allowing users to re-enable timestamping when negated (using `!NO_TIMESTAMP`). This inconsistency in flag behavior was not compliant with the expected functionality of other flags, leading to confusion and incorrect packet generation behavior.

        Commit message:
        pktgen: adjust flag NO_TIMESTAMP to be more pktgen compliant

Allow flag NO_TIMESTAMP to turn timestamping on again, like other flags,
with a negation of the flag like !NO_TIMESTAMP.

Also document the option flag NO_TIMESTAMP.

Fixes: afb84b626184 ("pktgen: add flag NO_TIMESTAMP to disable timestamping")
Signed-off-by: Jesper Dangaard Brouer <brouer@redhat.com>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:

 static ssize_t pktgen_if_write(struct file *file,
 			       const char __user * user_buffer, size_t count,
 			       loff_t * offset)
 {
 	struct seq_file *seq = file->private_data;
 	struct pktgen_dev *pkt_dev = seq->private;
 	int i, max, len;
 	char name[16], valstr[32];
 	unsigned long value = 0;
 	char *pg_result = NULL;
 	int tmp = 0;
 	char buf[128];

 	pg_result = &(pkt_dev->result[0]);

 	if (count < 1) {
 		pr_warn("wrong command format\n");
 		return -EINVAL;
 	}

 	max = count;
 	tmp = count_trail_chars(user_buffer, max);
 	if (tmp < 0) {
 		pr_warn("illegal format\n");
 		return tmp;
 	}
 	i = tmp;

 	/* Read variable name */

 	len = strn_len(&user_buffer[i], sizeof(name) - 1);
 	if (len < 0)
 		return len;

 	memset(name, 0, sizeof(name));
 	if (copy_from_user(name, &user_buffer[i], len))
 		return -EFAULT;
 	i += len;

 	max = count - i;
 	len = count_trail_chars(&user_buffer[i], max);
 	if (len < 0)
 		return len;

 	i += len;

 	if (debug) {
 		size_t copy = min_t(size_t, count, 1023);
 		char tb[copy + 1];
 		if (copy_from_user(tb, user_buffer, copy))
 			return -EFAULT;
 		tb[copy] = 0;
 		pr_debug("%s,%lu  buffer -:%s:-\n",
 			 name, (unsigned long)count, tb);
 	}

 	if (!strcmp(name, "min_pkt_size")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value < 14 + 20 + 8)
 			value = 14 + 20 + 8;
 		if (value != pkt_dev->min_pkt_size) {
 			pkt_dev->min_pkt_size = value;
 			pkt_dev->cur_pkt_size = value;
 		}
 		sprintf(pg_result, "OK: min_pkt_size=%u",
 			pkt_dev->min_pkt_size);
 		return count;
 	}

 	if (!strcmp(name, "max_pkt_size")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value < 14 + 20 + 8)
 			value = 14 + 20 + 8;
 		if (value != pkt_dev->max_pkt_size) {
 			pkt_dev->max_pkt_size = value;
 			pkt_dev->cur_pkt_size = value;
 		}
 		sprintf(pg_result, "OK: max_pkt_size=%u",
 			pkt_dev->max_pkt_size);
 		return count;
 	}

 	/* Shortcut for min = max */

 	if (!strcmp(name, "pkt_size")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value < 14 + 20 + 8)
 			value = 14 + 20 + 8;
 		if (value != pkt_dev->min_pkt_size) {
 			pkt_dev->min_pkt_size = value;
 			pkt_dev->max_pkt_size = value;
 			pkt_dev->cur_pkt_size = value;
 		}
 		sprintf(pg_result, "OK: pkt_size=%u", pkt_dev->min_pkt_size);
 		return count;
 	}

 	if (!strcmp(name, "debug")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		debug = value;
 		sprintf(pg_result, "OK: debug=%u", debug);
 		return count;
 	}

 	if (!strcmp(name, "frags")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		pkt_dev->nfrags = value;
 		sprintf(pg_result, "OK: frags=%u", pkt_dev->nfrags);
 		return count;
 	}
 	if (!strcmp(name, "delay")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value == 0x7FFFFFFF)
 			pkt_dev->delay = ULLONG_MAX;
 		else
 			pkt_dev->delay = (u64)value;

 		sprintf(pg_result, "OK: delay=%llu",
 			(unsigned long long) pkt_dev->delay);
 		return count;
 	}
 	if (!strcmp(name, "rate")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (!value)
 			return len;
 		pkt_dev->delay = pkt_dev->min_pkt_size*8*NSEC_PER_USEC/value;
 		if (debug)
 			pr_info("Delay set at: %llu ns\n", pkt_dev->delay);

 		sprintf(pg_result, "OK: rate=%lu", value);
 		return count;
 	}
 	if (!strcmp(name, "ratep")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (!value)
 			return len;
 		pkt_dev->delay = NSEC_PER_SEC/value;
 		if (debug)
 			pr_info("Delay set at: %llu ns\n", pkt_dev->delay);

 		sprintf(pg_result, "OK: rate=%lu", value);
 		return count;
 	}
 	if (!strcmp(name, "udp_src_min")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value != pkt_dev->udp_src_min) {
 			pkt_dev->udp_src_min = value;
 			pkt_dev->cur_udp_src = value;
 		}
 		sprintf(pg_result, "OK: udp_src_min=%u", pkt_dev->udp_src_min);
 		return count;
 	}
 	if (!strcmp(name, "udp_dst_min")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value != pkt_dev->udp_dst_min) {
 			pkt_dev->udp_dst_min = value;
 			pkt_dev->cur_udp_dst = value;
 		}
 		sprintf(pg_result, "OK: udp_dst_min=%u", pkt_dev->udp_dst_min);
 		return count;
 	}
 	if (!strcmp(name, "udp_src_max")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value != pkt_dev->udp_src_max) {
 			pkt_dev->udp_src_max = value;
 			pkt_dev->cur_udp_src = value;
 		}
 		sprintf(pg_result, "OK: udp_src_max=%u", pkt_dev->udp_src_max);
 		return count;
 	}
 	if (!strcmp(name, "udp_dst_max")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value != pkt_dev->udp_dst_max) {
 			pkt_dev->udp_dst_max = value;
 			pkt_dev->cur_udp_dst = value;
 		}
 		sprintf(pg_result, "OK: udp_dst_max=%u", pkt_dev->udp_dst_max);
 		return count;
 	}
 	if (!strcmp(name, "clone_skb")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;
 		if ((value > 0) &&
 		    (!(pkt_dev->odev->priv_flags & IFF_TX_SKB_SHARING)))
 			return -ENOTSUPP;
 		i += len;
 		pkt_dev->clone_skb = value;

 		sprintf(pg_result, "OK: clone_skb=%d", pkt_dev->clone_skb);
 		return count;
 	}
 	if (!strcmp(name, "count")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		pkt_dev->count = value;
 		sprintf(pg_result, "OK: count=%llu",
 			(unsigned long long)pkt_dev->count);
 		return count;
 	}
 	if (!strcmp(name, "src_mac_count")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (pkt_dev->src_mac_count != value) {
 			pkt_dev->src_mac_count = value;
 			pkt_dev->cur_src_mac_offset = 0;
 		}
 		sprintf(pg_result, "OK: src_mac_count=%d",
 			pkt_dev->src_mac_count);
 		return count;
 	}
 	if (!strcmp(name, "dst_mac_count")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (pkt_dev->dst_mac_count != value) {
 			pkt_dev->dst_mac_count = value;
 			pkt_dev->cur_dst_mac_offset = 0;
 		}
 		sprintf(pg_result, "OK: dst_mac_count=%d",
 			pkt_dev->dst_mac_count);
 		return count;
 	}
 	if (!strcmp(name, "burst")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if ((value > 1) &&
 		    (!(pkt_dev->odev->priv_flags & IFF_TX_SKB_SHARING)))
 			return -ENOTSUPP;
 		pkt_dev->burst = value < 1 ? 1 : value;
 		sprintf(pg_result, "OK: burst=%d", pkt_dev->burst);
 		return count;
 	}
 	if (!strcmp(name, "node")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;

 		if (node_possible(value)) {
 			pkt_dev->node = value;
 			sprintf(pg_result, "OK: node=%d", pkt_dev->node);
 			if (pkt_dev->page) {
 				put_page(pkt_dev->page);
 				pkt_dev->page = NULL;
 			}
 		}
 		else
 			sprintf(pg_result, "ERROR: node not possible");
 		return count;
 	}
 	if (!strcmp(name, "flag")) {
 		char f[32];
 		memset(f, 0, 32);
 		len = strn_len(&user_buffer[i], sizeof(f) - 1);
 		if (len < 0)
 			return len;

 		if (copy_from_user(f, &user_buffer[i], len))
 			return -EFAULT;
 		i += len;
 		if (strcmp(f, "IPSRC_RND") == 0)
 			pkt_dev->flags |= F_IPSRC_RND;

 		else if (strcmp(f, "!IPSRC_RND") == 0)
 			pkt_dev->flags &= ~F_IPSRC_RND;

 		else if (strcmp(f, "TXSIZE_RND") == 0)
 			pkt_dev->flags |= F_TXSIZE_RND;

 		else if (strcmp(f, "!TXSIZE_RND") == 0)
 			pkt_dev->flags &= ~F_TXSIZE_RND;

 		else if (strcmp(f, "IPDST_RND") == 0)
 			pkt_dev->flags |= F_IPDST_RND;

 		else if (strcmp(f, "!IPDST_RND") == 0)
 			pkt_dev->flags &= ~F_IPDST_RND;

 		else if (strcmp(f, "UDPSRC_RND") == 0)
 			pkt_dev->flags |= F_UDPSRC_RND;

 		else if (strcmp(f, "!UDPSRC_RND") == 0)
 			pkt_dev->flags &= ~F_UDPSRC_RND;

 		else if (strcmp(f, "UDPDST_RND") == 0)
 			pkt_dev->flags |= F_UDPDST_RND;

 		else if (strcmp(f, "!UDPDST_RND") == 0)
 			pkt_dev->flags &= ~F_UDPDST_RND;

 		else if (strcmp(f, "MACSRC_RND") == 0)
 			pkt_dev->flags |= F_MACSRC_RND;

 		else if (strcmp(f, "!MACSRC_RND") == 0)
 			pkt_dev->flags &= ~F_MACSRC_RND;

 		else if (strcmp(f, "MACDST_RND") == 0)
 			pkt_dev->flags |= F_MACDST_RND;

 		else if (strcmp(f, "!MACDST_RND") == 0)
 			pkt_dev->flags &= ~F_MACDST_RND;

 		else if (strcmp(f, "MPLS_RND") == 0)
 			pkt_dev->flags |= F_MPLS_RND;

 		else if (strcmp(f, "!MPLS_RND") == 0)
 			pkt_dev->flags &= ~F_MPLS_RND;

 		else if (strcmp(f, "VID_RND") == 0)
 			pkt_dev->flags |= F_VID_RND;

 		else if (strcmp(f, "!VID_RND") == 0)
 			pkt_dev->flags &= ~F_VID_RND;

 		else if (strcmp(f, "SVID_RND") == 0)
 			pkt_dev->flags |= F_SVID_RND;

 		else if (strcmp(f, "!SVID_RND") == 0)
 			pkt_dev->flags &= ~F_SVID_RND;

 		else if (strcmp(f, "FLOW_SEQ") == 0)
 			pkt_dev->flags |= F_FLOW_SEQ;

 		else if (strcmp(f, "QUEUE_MAP_RND") == 0)
 			pkt_dev->flags |= F_QUEUE_MAP_RND;

 		else if (strcmp(f, "!QUEUE_MAP_RND") == 0)
 			pkt_dev->flags &= ~F_QUEUE_MAP_RND;

 		else if (strcmp(f, "QUEUE_MAP_CPU") == 0)
